// ValidateWorkspaceResponse runs the validations defined on WorkspaceResponse
func ValidateWorkspaceResponse(body *WorkspaceResponse) (err error) {
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Namespace == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("namespace", "body"))
	}
	if body.Image == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("image", "body"))
	}
	if body.ReadyReplicas == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("ready_replicas", "body"))
	}
	if body.Stopped == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("stopped", "body"))
	}
	if body.ContainerState != nil {
		if err2 := ValidateContainerStateResponse(body.ContainerState); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	for _, e := range body.VolumeMounts {
		if e != nil {
			if err2 := ValidateVolumeMountResponse(e); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	return
}

